// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(address(c), 1 ether);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll(nonOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
